--Settings
SafeAddString(NEW_DIALOG_ORDER_USE_ACCOUNTWIDE, "Использовать общий профиль аккаунта", 1)
SafeAddString(NEW_DIALOG_ORDER_UNREAD_TO_FRONT, "Непрочитанные вверх", 1)
SafeAddString(NEW_DIALOG_ORDER_UNREAD_TO_FRONT_DESC, "Ставить еще не выбранные опции (белые) поверх уже выбранных ранее (серых).", 1)
SafeAddString(NEW_DIALOG_ORDER_KEEP_CONVERSATION, "Продолжить диалог", 1)
SafeAddString(NEW_DIALOG_ORDER_KEEP_CONVERSATION_DESC, "Когда вы выбираете опцию диалога, следующие варианты ответов, которые игра воспринимает как продолжение разговора, будут перемещены вверх, даже выше приоритетных опций (банк, магазин и т.д.). Это обеспечивает естественный ход беседы, при котором, если вы намеренно начинаете обсуждать что-либо, опции банка/магазина не будут вам мешать.", 1)
SafeAddString(NEW_DIALOG_ORDER_CUSTOMIZE, "Свой порядок сортировки", 1)
SafeAddString(NEW_DIALOG_ORDER_CUSTOMIZE_DESC, "По умолчанию аддон не меняет порядок функциональных опций диалога между собой. Только порядок относительно остальных - разговорных - опций.\nЕсли в диалоге банкира идут 'Банк', 'Банк гильдии', а затем 'Магазин гильдии', то в таком же порядке они будут перемещены в начало списка.\nЕсли хотите, чтобы 'Банк гильдии' был первым перед 'Банком', включите эту опцию и настройте свой порядок сортировки в меню ниже", 1)
SafeAddString(NEW_DIALOG_ORDER_PRIORITY_ORDER, "Приоритет сортировки", 1)
SafeAddString(NEW_DIALOG_ORDER_UNMANAGED, "Стандартный порядок", 1)
SafeAddString(NEW_DIALOG_ORDER_MANAGE_DESC, "Выбор приоритета опций в диалогах.\n'Стандартный порядок' значит, что опция будет считаться обычной разговорной опцией и не будет поднята выше.", 1)

